void look_6(inout Look k) {
  p_adCard = L6_adCard;
  p_adInk = L6_adInk;
  p_adSky = L6_adSky;
  p_adEarth = L6_adEarth;
  p_adMark = L6_adMark;
  p_adGreen = L6_adGreen;
  p_adRed = L6_adRed;
  p_adCell = L6_adCell;
  p_adLit = L6_adLit;
  p_adRough = L6_adRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 adP;
    float adR, adKind, adSeed;
    if (s2.x > 0.001) {
      adP = s3 / (s2.x * 0.5);
      adR = s2.x * 0.5;
      adKind = floor(s2.z + 0.5);
      adSeed = seed + s2.z * 3.3;
    } else {
      vec2 adC = floor(uv / p_adCell);
      adP = (fract(uv / p_adCell) - 0.5) * 2.0;
      adR = p_adCell * 0.5;
      adKind = floor(kh1(adC.x * 7.0 + adC.y * 13.0 + seed) * 5.0);
      adSeed = seed + adC.x * 1.7 + adC.y * 5.1;
    }
    if (adKind > 4.5) adKind = 0.0;
    float adD = length(adP);
    float adE = fwidth(adD) * 0.75 + 0.0005;
    float adA = atan(adP.x, adP.y) / 6.2831853;
    float adH1 = kh1(adSeed * 1.3 + 2.0), adH2 = kh1(adSeed * 2.9 + 5.0);
    vec3 c = p_adCard;
    float adInk = 0.0;
    vec3 adTint = p_adInk;
    if (adKind < 0.5) {
      // gauge: three quarters of the rim, from seven o'clock round to five
      float adOn = step(abs(adA), 0.375);
      adInk = adOn * max(adMarks(adA, 40.0, 0.012, adD, 0.8, 0.92, adE), adMarks(adA, 8.0, 0.022, adD, 0.7, 0.92, adE));
      adInk = max(adInk, adNeedle(adP, (adH1 - 0.5) * 4.4, 0.78, 0.045, adE));
    } else if (adKind < 1.5) {
      // attitude: the horizon tipped and shifted, sky over earth, a white line between, the aircraft mark fixed
      float adTip = (adH1 - 0.5) * 0.7;
      float adY = adP.y * cos(adTip) - adP.x * sin(adTip) - (adH2 - 0.5) * 0.4;
      c = mix(p_adEarth, p_adSky, smoothstep(-adE, adE, adY));
      adInk = 1.0 - smoothstep(0.012, 0.012 + adE, abs(adY));
      // pitch bars
      float adX = adP.x * cos(adTip) + adP.y * sin(adTip);
      float adBar = abs(fract(adY * 5.0 + 0.5) - 0.5) / 5.0;
      adInk = max(adInk, (1.0 - smoothstep(0.008, 0.008 + adE, adBar)) * step(abs(adX), 0.16) * step(abs(adY), 0.5));
      float adWing = step(abs(adP.y), 0.025) * step(0.18, abs(adP.x)) * step(abs(adP.x), 0.6) + step(length(adP), 0.05);
      c = mix(c, p_adMark, clamp(adWing, 0.0, 1.0));
    } else if (adKind < 2.5) {
      adInk = max(adMarks(adA, 50.0, 0.01, adD, 0.82, 0.92, adE), adMarks(adA, 10.0, 0.022, adD, 0.7, 0.92, adE));
      adInk = max(adInk, adNeedle(adP, adH1 * 6.2831853, 0.8, 0.03, adE));
      adInk = max(adInk, adNeedle(adP, adH2 * 6.2831853, 0.48, 0.06, adE));
    } else if (adKind < 3.5) {
      adInk = max(adMarks(adA + adH1, 36.0, 0.01, adD, 0.84, 0.92, adE), adMarks(adA + adH1, 12.0, 0.018, adD, 0.76, 0.92, adE));
      adInk = max(adInk, adMarks(adA + adH1, 4.0, 0.03, adD, 0.62, 0.92, adE));
      float adLub = (1.0 - smoothstep(0.02, 0.02 + adE, abs(adP.x))) * step(0.55, adP.y) * step(adP.y, 0.98);
      c = mix(c, p_adMark, adLub);
      // the aircraft's own outline at the middle
      adInk = max(adInk, step(abs(adP.x), 0.03) * step(abs(adP.y), 0.3) + step(abs(adP.y - 0.05), 0.03) * step(abs(adP.x), 0.22));
    } else {
      // engine gauge: a quarter arc at the top left to top right, a green band, a red line at its end
      float adOn = step(abs(adA), 0.19);
      float adArc = smoothstep(0.8 - adE, 0.8, adD) * (1.0 - smoothstep(0.9, 0.9 + adE, adD));
      c = mix(c, p_adGreen, adArc * step(-0.08, adA) * step(adA, 0.1));
      c = mix(c, p_adRed, adArc * step(0.15, adA) * step(adA, 0.19));
      adInk = adOn * adMarks(adA, 32.0, 0.014, adD, 0.68, 0.8, adE);
      adInk = max(adInk, adNeedle(adP, (adH1 - 0.5) * 2.2, 0.76, 0.045, adE));
    }
    adInk = clamp(adInk, 0.0, 1.0);
    // the hub, and the bezel's shade at the rim
    float adHub = 1.0 - smoothstep(0.09, 0.09 + adE, adD);
    c = mix(c, adTint, adInk);
    c = mix(c, vec3(0.02), adHub * step(adKind, 0.5) + adHub * step(1.5, adKind) * step(adKind, 2.5) + adHub * step(3.5, adKind));
    // finer than a pixel, the dial is the grey its marks make
    float adF = kfade(0.12 * adR);
    c = mix(mix(p_adCard, p_adInk, 0.12), c, adF);
    c *= 1.0 - 0.6 * smoothstep(0.9, 1.0, adD);
    k.colour = c;
    k.metal = 0.0;
    k.rough = p_adRough;
    k.glow = p_adLit * c * (1.0 - 0.5 * adD);

}

void look_7(inout Look k) {
  p_fcColour = L7_fcColour;
  p_fcCells = L7_fcCells;
  p_fcFine = L7_fcFine;
  p_fcDepth = L7_fcDepth;
  p_fcFineDepth = L7_fcFineDepth;
  p_fcTone = L7_fcTone;
  p_fcMetal = L7_fcMetal;
  p_fcRough = L7_fcRough;
  p_fcSeam = L7_fcSeam;
  p_fcTape = L7_fcTape;
  p_fcDust = L7_fcDust;
  p_fcDustColour = L7_fcDustColour;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the creased facets: a pit in each cell, its rim the creases; and the finer crumple over it
    float fcId, fcEdge, fcId2, fcEdge2;
    vec2 fcP = uv * p_fcCells + seed * 13.0;
    float fcD = kvor(fcP, fcId, fcEdge);
    float fcD2 = kvor(fcP * p_fcFine + 5.1, fcId2, fcEdge2);
    float fcF = kfade(1.0 / p_fcCells), fcF2 = kfade(1.0 / (p_fcCells * p_fcFine));
    float fcH = (fcD * (0.6 + 0.8 * fcId) - 0.5) * fcF + p_fcFineDepth * (fcD2 - 0.5) * fcF2;
    // the tape over each seam, flat and duller
    float fcS = abs(fract(uv.y / p_fcSeam + 0.5) - 0.5) * p_fcSeam;
    float fcT = (1.0 - smoothstep(p_fcTape * 0.5 - 0.001, p_fcTape * 0.5, fcS)) * kfade(p_fcTape);
    float fcTone = 1.0 + p_fcTone * (fcId - 0.5) * 2.0 * fcF;
    vec3 fcC = p_fcColour * fcTone;
    fcC = mix(fcC, p_fcColour * 0.85, fcT);
    // dust: settled in a slow cloud, thicker in the pits
    float fcDu = clamp(p_fcDust * (0.5 + kfbm4(uv * 3.0 + seed + 2.0)) * (0.8 + 0.4 * fcD * fcF), 0.0, 1.0);
    k.colour = mix(fcC, p_fcDustColour, fcDu * 0.7);
