void look_13(inout Look k) {
  p_pvCellColour = L13_pvCellColour;
  p_pvBack = L13_pvBack;
  p_pvBar = L13_pvBar;
  p_pvCell = L13_pvCell;
  p_pvGap = L13_pvGap;
  p_pvCorner = L13_pvCorner;
  p_pvBars = L13_pvBars;
  p_pvBarWide = L13_pvBarWide;
  p_pvFinger = L13_pvFinger;
  p_pvShade = L13_pvShade;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 pvP = uv / p_pvCell;
    vec2 pvId = floor(pvP);
    vec2 pvQ = (fract(pvP) - 0.5) * p_pvCell;
    float pvHalf = p_pvCell * 0.5 - p_pvGap * 0.5;
    // inside the cell: a square with its corners cut at 45 degrees
    vec2 pvA = abs(pvQ);
    float pvIn = step(max(pvA.x, pvA.y), pvHalf) * step(pvA.x + pvA.y, 2.0 * pvHalf - p_pvCorner);
    float pvInF = mix(1.0 - p_pvGap / p_pvCell * 2.0, pvIn, kfade(p_pvGap * 2.0));
    // the busbars along v, evenly across the cell, and the fingers along u
    float pvBarAt = (pvQ.x / (2.0 * pvHalf) + 0.5) * p_pvBars;
    float pvBarD = abs(fract(pvBarAt) - 0.5) * 2.0 * pvHalf / p_pvBars;
    float pvBarF = kfade(p_pvBarWide * 2.0);
    float pvBar = mix(p_pvBarWide * p_pvBars / p_pvCell, step(pvBarD, p_pvBarWide * 0.5), pvBarF);
    float pvFinD = abs(fract(pvQ.y / p_pvFinger) - 0.5) * p_pvFinger;
    float pvFinF = kfade(p_pvFinger);
    float pvFin = mix(0.08, step(pvFinD, 0.00012), pvFinF) * 0.35;
    float pvShadeC = 1.0 + (kh(pvId + seed) - 0.5) * 2.0 * p_pvShade;
    vec3 pvCellC = p_pvCellColour * pvShadeC;
    pvCellC = mix(pvCellC, p_pvBar, clamp(pvBar + pvFin, 0.0, 1.0));
    k.colour = mix(p_pvBack, pvCellC, pvInF);
    k.metal = 0.6 * pvBar * pvInF;
    k.rough = mix(0.5, 0.2, pvInF);
    k.height = -0.0002 * (1.0 - pvInF);
    k.clearcoat = 1.0;
    k.clearcoatRough = 0.02;

}

