  } else if (kind < 4.5) {
    // terry: loops standing up, each a soft tuft in jittered cells, the ground weave between them
    float id, e;
    float d = kvor(q, id, e);
    float tuft = 1.0 - smoothstep(0.1, 0.55, d);
    return vec2(0.25 + 0.75 * tuft, 0.6 + 0.4 * fract(id * 17.1));
  }
  // braid: plaited yarns, a herringbone along u
  float side = sign(fract(q.y * 0.5) - 0.5);
  float s = fract(q.x * 0.7 + side * q.y * 0.7);
  float h = abs(sin(s * 3.14159));
  return vec2(h, step(0.0, side));
}
// a small leaf printed on cotton, repeated rep metres apart, each turned its own way: 1 on the leaf
float upLeaf(vec2 p, float rep, float seed) {
  vec2 cell = floor(p / rep);
  vec2 f = fract(p / rep) - 0.5;
  float a = kh(cell + seed) * 6.2831853;
  vec2 r = vec2(cos(a) * f.x + sin(a) * f.y, -sin(a) * f.x + cos(a) * f.y);
  r += (vec2(kh(cell + 3.1), kh(cell + 5.7)) - 0.5) * 0.15;
  float blade = length(vec2(r.x * 2.6, r.y * 1.0 + 0.4 * r.x * r.x * 8.0));
  float leafM = 1.0 - smoothstep(0.26, 0.29, blade);
  float rib = 1.0 - smoothstep(0.0, 0.02, abs(r.x));
  return leafM * (1.0 - 0.6 * rib * step(abs(r.y), 0.25));
}

void look_0(inout Look k) {
  p_glTint = L0_glTint;
  p_glTint2 = L0_glTint2;
  p_glWaves = L0_glWaves;
  p_glWaveDepth = L0_glWaveDepth;
  p_glSeeds = L0_glSeeds;
  p_glRough = L0_glRough;
  p_glAlpha = L0_glAlpha;
  p_glAlphaVar = L0_glAlphaVar;
  p_glRibs = L0_glRibs;
  p_glRibWide = L0_glRibWide;
  p_glRibAlpha = L0_glRibAlpha;
  p_glGlow = L0_glGlow;
  p_glCrease = L0_glCrease;
  p_glCreaseFreq = L0_glCreaseFreq;
  p_glBands = L0_glBands;
  p_glBandHigh = L0_glBandHigh;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float wave = kfbm4(uv * p_glWaves + seed);
    float seeds = smoothstep(0.08, 0.02, kcell(uv * 60.0 + seed)) * kfade(0.01);
    // the twin wall's ribs, along u, one every 1 / glRibs metres across v; under a pixel, their mean cover
    float glRib = 0.0;
    if (p_glRibs > 0.0) {
      float glRd = abs(fract(uv.y * p_glRibs) - 0.5) * 2.0;
      float glRw = fwidth(uv.y * p_glRibs) * 2.0;
      float glLine = 1.0 - smoothstep(p_glRibWide - glRw, p_glRibWide + glRw, 1.0 - glRd);
      glRib = mix(p_glRibWide, glLine, kfade(1.5 / p_glRibs));
    }
    // the film's creases and wound bands, level round the load (the world's height, and the way along the face)
    float glFold = 0.0, glBand = 0.0;
    if (p_glCrease > 0.0 || p_glBands > 0.0) {
      vec3 glSide = cross(vec3(0.0, 1.0, 0.0), wn);
      float glAlong = dot(glSide, glSide) > 0.01 ? dot(wp, normalize(glSide)) : wp.x;
      float glUp = wp.y + 0.03 * kn(vec2(glAlong * 2.0, 0.0) + seed);
      float glF = kn(vec2(glAlong * 1.6, glUp * p_glCreaseFreq) + seed * 1.7);
      float glF2 = kn(vec2(glAlong * 3.1, glUp * p_glCreaseFreq * 2.3) + seed + 5.0);
      glFold = p_glCrease * mix(0.35, pow(1.0 - abs(glF * 2.0 - 1.0), 6.0) * 0.75 + pow(1.0 - abs(glF2 * 2.0 - 1.0), 8.0) * 0.4,
                                kfade(1.0 / p_glCreaseFreq));
      float glB = fract(glUp / p_glBandHigh + 0.15 * kn(vec2(glAlong * 0.8, 3.0) + seed));
      glBand = p_glBands * smoothstep(0.55, 0.62, glB) * (0.8 + 0.4 * kn(vec2(glAlong * 4.0, glUp * 6.0) + seed));
    }
    k.colour = mix(p_glTint, p_glTint2, wave) + seeds * p_glSeeds + vec3(0.12 * glRib + 0.25 * glFold + 0.06 * glBand);
    k.rough = p_glRough + p_glRough * wave;
    k.metal = 0.0;
    k.height = p_glWaveDepth * (wave - 0.5) + 0.0003 * glFold;
    k.alpha = clamp(p_glAlpha + p_glAlphaVar * wave + p_glRibAlpha * glRib + 0.35 * glFold + 0.18 * glBand, 0.0, 1.0);
    k.glow = p_glGlow * (0.9 + 0.2 * wave) * (1.0 + 0.4 * glRib);

}

void look_1(inout Look k) {
  p_stColour = L1_stColour;
  p_stMetal = L1_stMetal;
  p_stRough = L1_stRough;
  p_stOil = L1_stOil;
  p_stOilColour = L1_stOilColour;
  p_stOilBrown = L1_stOilBrown;
  p_stOilSize = L1_stOilSize;
  p_stOilRough = L1_stOilRough;
  p_stFinPitch = L1_stFinPitch;
  p_stFinShare = L1_stFinShare;
  p_stFinDepth = L1_stFinDepth;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float brush = kn(vec2(uv.x * 4.0, uv.y * 900.0) + seed) * kfade(0.002);
    float wear = kfbm(uv * 3.0 + seed);
    vec3 stC = p_stColour * (0.9 + 0.12 * brush) * (0.9 + 0.15 * wear);
    float stM = p_stMetal;
    float stR = p_stRough + 0.15 * brush + 0.1 * wear;
    float stH = 0.00005 * brush;
    // fins: a rounded ridge of share stFinShare in each pitch along s3.x, the groove between them the depth down and
    // dark (the normal they bend is worked out below); fading to the fins' mean where a pitch is under a few pixels
    float stOn = step(0.5, s3.y);
    float stFade = kfade(p_stFinPitch * 4.0);
    float stF = fract(s3.x / p_stFinPitch);
    float stRidge = smoothstep(1.0 - 2.0 * p_stFinShare, 1.0, 0.5 + 0.5 * cos(6.28318 * stF));
    // far off, the fins' mean: the ridges' share lit, the rest groove
    float stShade = mix(p_stFinShare, stRidge, stFade);
    stC *= mix(1.0, 0.55 + 0.45 * stShade, stOn);
    // burnt castor oil: blotches and runs of a brown-black varnish; thick (glossy, brown in its highlight) or thin
    float stBlot = kfbm(uv * p_stOilSize + seed * 1.7);
    float stRun = kn(vec2(uv.x * p_stOilSize * 0.6, uv.y * p_stOilSize * 9.0) + seed + 11.0);
    float stThick = smoothstep(0.35, 0.75, 0.65 * stBlot + 0.35 * stRun);
    float stO = clamp(p_stOil * (0.75 + 0.35 * stThick), 0.0, 1.0);
    vec3 stOilC = mix(p_stOilColour, p_stOilBrown, stThick * (0.5 + 0.5 * kn(uv * 60.0 + seed)));
    stC = mix(stC, stOilC * mix(1.0, 0.6 + 0.4 * stShade, stOn), stO);
    stM = mix(stM, 0.12, stO);
    stR = mix(stR, mix(0.75, p_stOilRough, stThick), stO);
    stH += p_stOil * 0.00004 * stThick;
    k.colour = stC;
    k.metal = stM;
    k.rough = stR;
    k.height = stH;
    if (stOn > 0.5) {
      // the fins bend the normal from their profile's slope worked out exactly, not from the pixels' neighbours (whose
      // steps break thin rings into dots): the way s3.x grows across the surface, in the view's ways, from its change
      // between pixels (it is even across a face, so this is clean), times the profile's slope along it
      vec3 stN = normalize(vNormal);
      vec3 stPx = dFdx(-vViewPosition), stPy = dFdy(-vViewPosition);
      vec3 stR1 = cross(stPy, stN), stR2 = cross(stN, stPx);
      float stDet = dot(stPx, stR1);
      vec3 stG = (dFdx(s3.x) * stR1 + dFdy(s3.x) * stR2) / (abs(stDet) > 1e-14 ? stDet : 1e-14);
      float stPhi = 6.28318 * stF;
      float stA = 1.0 - 2.0 * p_stFinShare;
      float stT = clamp((0.5 + 0.5 * cos(stPhi) - stA) / (1.0 - stA), 0.0, 1.0);
      float stSlope = p_stFinDepth * 6.0 * stT * (1.0 - stT) / (1.0 - stA) * (-0.5 * sin(stPhi) * 6.28318 / p_stFinPitch);
      k.normal = normalize(stN - stFade * stSlope * stG);
      k.ownNormal = true;
    }

}

void look_2(inout Look k) {
  p_rbColour = L2_rbColour;
  p_rbBloom = L2_rbBloom;
  p_rbBloomAmount = L2_rbBloomAmount;
  p_rbGrit = L2_rbGrit;
  p_rbRelief = L2_rbRelief;
  p_rbRough = L2_rbRough;
  p_rbSheen = L2_rbSheen;
  p_rbSheenRough = L2_rbSheenRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float rbG = kn(uv * p_rbGrit + seed) * kfade(2.0 / p_rbGrit);
    float rbP = 1.0 - smoothstep(0.0, 0.25, kcell(uv * p_rbGrit * 0.25 + seed)) ;
    rbP *= kfade(6.0 / p_rbGrit);
    float rbB = smoothstep(0.35, 0.8, kfbm4(uv * 4.0 + seed)) * p_rbBloomAmount;
    k.colour = mix(p_rbColour, p_rbBloom, rbB) * (0.95 + 0.1 * rbG) * (1.0 - 0.3 * rbP);
    k.rough = clamp(p_rbRough + 0.08 * rbB + 0.05 * rbG, 0.0, 1.0);
    k.height = p_rbRelief * (rbG - 0.6 * rbP);
    k.sheen = p_rbSheen;
    k.sheenRough = p_rbSheenRough;

}

void look_3(inout Look k) {
  p_pmColour = L3_pmColour;
  p_pmPeel = L3_pmPeel;
  p_pmRelief = L3_pmRelief;
  p_pmRough = L3_pmRough;
  p_pmCoat = L3_pmCoat;
  p_pmCoatRough = L3_pmCoatRough;
  p_pmOil = L3_pmOil;
  p_pmOilColour = L3_pmOilColour;
  p_pmOilStreaks = L3_pmOilStreaks;
  p_pmOilRough = L3_pmOilRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float pmF = kfade(2.0 / p_pmPeel);
    float pmPeel = (1.0 - kcell(uv * p_pmPeel + seed)) * pmF;
    float pmFine = kn(uv * p_pmPeel * 2.7 + seed + 3.0) * kfade(1.0 / p_pmPeel);
    k.colour = p_pmColour * (0.985 + 0.03 * kfbm4(uv * 2.0 + seed));
    k.rough = clamp(p_pmRough + 0.04 * pmFine, 0.0, 1.0);
    k.height = p_pmRelief * (0.75 * pmPeel + 0.25 * pmFine);
    k.clearcoat = p_pmCoat;
    k.clearcoatRough = p_pmCoatRough;
    if (p_pmOil > 0.0) {
      // runs: noise drawn out along u, fine across v; blotches: a slow fbm; thick where both lie
      float pmRun = kn(vec2(uv.x * p_pmOilStreaks * 0.12, uv.y * p_pmOilStreaks) + seed + 5.0);
      float pmBlot = kfbm(uv * 2.5 + seed + 9.0);
      float pmThick = smoothstep(0.4, 0.8, 0.55 * pmRun + 0.45 * pmBlot);
      float pmO = clamp(p_pmOil * (0.15 + 0.85 * pmThick), 0.0, 1.0);
      vec3 pmOilC = p_pmOilColour * (0.7 + 0.6 * kn(vec2(uv.x * 3.0, uv.y * 40.0) + seed));
      k.colour = mix(k.colour, pmOilC, pmO);
      k.rough = mix(k.rough, p_pmOilRough + 0.5 * (1.0 - pmThick), pmO);
      k.clearcoat = mix(k.clearcoat, 0.0, pmO);
      k.height += p_pmOil * 0.00006 * pmThick;
    }

}

void look_4(inout Look k) {
  p_bmColour = L4_bmColour;
  p_bmLines = L4_bmLines;
  p_bmStreak = L4_bmStreak;
  p_bmLong = L4_bmLong;
  p_bmRough = L4_bmRough;
  p_bmMetal = L4_bmMetal;
  p_bmRelief = L4_bmRelief;
  p_bmMirror = L4_bmMirror;
  p_bmSky = L4_bmSky;
  p_bmWall = L4_bmWall;
  p_bmFloor = L4_bmFloor;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 bmG = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(1.0, 0.0);
    // along the brushing, across it
    vec2 bmQ = vec2(dot(uv, bmG), dot(uv, vec2(-bmG.y, bmG.x)));
    // the scratches: noise stretched far along the brushing, one row a scratch, faded to its mean where a scratch is
    // under a pixel; a few deeper, longer ones over them
    float bmFine = mix(0.5, kn(vec2(bmQ.x * p_bmLong * 4.0, bmQ.y * p_bmLines) + seed), kfade(2.0 / p_bmLines));
    float bmDeep = mix(0.5, kn(vec2(bmQ.x * p_bmLong, bmQ.y * p_bmLines * 0.18) + seed + 17.0), kfade(8.0 / p_bmLines));
    float bmS = 0.75 * bmFine + 0.25 * smoothstep(0.35, 0.8, bmDeep);
    // a slow cloud of the belt's passes, so a big sheet isn't one flat grey
    float bmPass = kfbm4(vec2(bmQ.x * 0.6, bmQ.y * 7.0) + seed * 1.3);
    vec3 bmC = p_bmColour * (1.0 + p_bmStreak * (bmS - 0.5) * 0.9) * (0.94 + 0.12 * bmPass);
    k.colour = bmC;
    k.metal = p_bmMetal;
    k.rough = clamp(p_bmRough + 0.12 * (bmS - 0.5) + 0.05 * (bmPass - 0.5), 0.03, 1.0);
    k.height = p_bmRelief * (bmS - 0.5);
    // the room mirrored, smeared along the brushing: its ray tipped across the scratches by each one's slope
    vec3 bmV = normalize(wp - cameraPosition);
    vec3 bmN = normalize(wn);
    vec3 bmR = reflect(bmV, bmN);
    float bmCos = clamp(dot(-bmV, bmN), 0.0, 1.0);
    float bmFres = 0.7 + 0.3 * pow(1.0 - bmCos, 3.0);
    vec3 bmRoom = rmRoom(normalize(bmR + 0.08 * (bmS - 0.5) * vec3(1.0, 0.0, 1.0)), clamp(p_bmRough * 2.2, 0.0, 1.0), p_bmSky, p_bmWall, p_bmFloor);
    k.glow = p_bmMirror * bmRoom * bmC * bmFres * (0.85 + 0.3 * bmS);
    if (lookView > 0.5 && lookView < 1.5) k.colour = vec3(0.5 + 0.5 * bmG.x, 0.5 + 0.5 * bmG.y, 0.5);

}

