void look_18(inout Look k) {
  p_upKind = L18_upKind;
  p_upColour = L18_upColour;
  p_upColour2 = L18_upColour2;
  p_upThread = L18_upThread;
  p_upFleck = L18_upFleck;
  p_upPrint = L18_upPrint;
  p_upMotif = L18_upMotif;
  p_upRelief = L18_upRelief;
  p_upSheen = L18_upSheen;
  p_upRough = L18_upRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // a loop's or a thread's own detail (its ring, its crossing) is half of it across: faded out before it aliases
    float upF = kfade(p_upThread * 0.5);
    vec2 cl = upCloth(uv, p_upKind, p_upThread, seed);
    float h = mix(0.5, cl.x, upF);
    float lite = mix(0.5, cl.y, upF);
    // heather: fibres of the second colour twisted into the yarn, finer than a thread
    float fleck = smoothstep(0.55, 0.85, kn(uv / (p_upThread * 0.7) + seed * 3.0));
    float fleckMean = 0.18;
    float heather = p_upFleck * mix(fleckMean, fleck, kfade(p_upThread * 0.7));
    vec3 col = mix(p_upColour, p_upColour2, heather);
    // the dye's slow unevenness over the cloth
    col *= 0.94 + 0.1 * kfbm4(uv * 4.0 + seed);
    // the print: leaves in the second colour, then the weave over it
    float leaf = upLeaf(uv, p_upMotif, seed) * kfade(p_upMotif * 0.2);
    float leafMean = 0.12;
    col = mix(col, p_upColour2, p_upPrint * mix(leafMean, leaf, kfade(p_upMotif * 0.2)));
    // low places in shadow of the yarn round them, high places catch the light; a mesh's holes dark
    // (a loop pile, bouclé or terry, is soft: its loops shade one another only a little)
    bool upLoops = (p_upKind > 1.5 && p_upKind < 2.5) || (p_upKind > 3.5 && p_upKind < 4.5);
    float shade = p_upKind > 2.5 && p_upKind < 3.5 ? mix(0.25, 1.0, h) : upLoops ? 0.88 + 0.15 * h : 0.78 + 0.3 * h;
    col *= shade * (upLoops ? 0.95 + 0.07 * lite : 0.92 + 0.12 * lite);
    // a loop pile's yarn bunches: clumps of loops a few loops across, standing proud or sinking, seen from across a room
    float clump = upLoops ? kfbm4(uv / (p_upThread * 3.0) + seed) : 0.5;
    float clumpF = kfade(p_upThread * 1.5);
    clump = mix(0.5, clump, clumpF);
    col *= 0.86 + 0.28 * clump;
    h = mix(h, clump, upLoops ? 0.6 : 0.0);
    k.colour = col;
    k.rough = p_upRough;
    k.height = p_upRelief * h;
    k.ao = mix(0.75, 1.0, h);
    k.sheen = mix(p_upColour, vec3(1.0), 0.35) * p_upSheen;
    k.sheenRough = 0.7;

}




















